import functools


def wrap_coroutine(api, coroutine):
    @functools.wraps(coroutine)
    async def wrapper(*args, **kwargs):
        with api as time_factory:
            if api.as_arg:
                # Pass the frozen time object as an argument if `as_arg` is True
                result = await coroutine(time_factory, *args, **kwargs)
            else:
                # Only call the coroutine with its own arguments
                result = await coroutine(*args, **kwargs)
        return result

    return wrapper

